// The OpenAPI v3 documents of the pinned version, one per served group version, rebuilt from the
// vendored data (generated by npm run api:vendor, tools/src/openapi/vendor.ts, which documents the
// format). They hold the schema keys kubectl explain reads and each operation's
// x-kubernetes-group-version-kind; the parameters, responses and other annotations of the real
// documents are not vendored. Parsed on first use and kept as a derived cache outside world state
// (docs/ARCHITECTURE.md §2.12): it is static data.

import type { JsonObject } from '../apimachinery/json.ts';
import { DATA } from './data/v1.37.2.openapiv3.ts';

interface RawData {
  version: string;
  defs: Record<string, JsonObject>;
  gvs: Record<string, { s: number[]; p: Record<string, Record<string, string>>; o?: Record<string, JsonObject> }>;
}

let raw: RawData | undefined;
let names: string[] | undefined;
const documents: Record<string, JsonObject> = {};

function data(): RawData {
  raw ??= JSON.parse(DATA) as RawData;
  names ??= Object.keys(raw.defs).sort();
  return raw;
}

/** The group versions with a document, as `/openapi/v3` names them: `api/v1`, `apis/apps/v1`. */
export function openApiV3Paths(): string[] {
  return Object.keys(data().gvs);
}

function gvk(s: string): JsonObject {
  const [group, version, kind] = s.split('/') as [string, string, string];
  return { group, kind, version };
}

/**
 * The document of a group version (`apis/apps/v1`), or undefined when it has none. The returned
 * object is shared: callers must not change it.
 */
export function openApiV3Document(path: string): JsonObject | undefined {
  const hit = documents[path];
  if (hit) return hit;
  const d = data();
  const gv = d.gvs[path];
  if (!gv) return undefined;
  const schemas: JsonObject = {};
  for (const i of gv.s) {
    const name = (names as string[])[i] as string;
    const own = gv.o?.[name];
    schemas[name] = own ? { ...(d.defs[name] as JsonObject), ...own } : (d.defs[name] as JsonObject);
  }
  const paths: JsonObject = {};
  for (const [p, ops] of Object.entries(gv.p)) {
    const item: JsonObject = {};
    for (const [method, k] of Object.entries(ops)) item[method] = { 'x-kubernetes-group-version-kind': gvk(k) };
    paths[p] = item;
  }
  // upstream: the header of the checked-in documents (api/openapi-spec/v3/*.json)
  const doc: JsonObject = { openapi: '3.0.0', info: { title: 'Kubernetes', version: 'unversioned' }, paths, components: { schemas } };
  documents[path] = doc;
  return doc;
}
